const payload = $input.first().json.body ?? {};
const event = String(payload.event ?? '').toLowerCase().replace(/_/g, '.');
const data = payload.data ?? {};
const key = data.key ?? {};
const jid = String(key.remoteJid ?? '');
const text = String(data.message?.conversation ?? data.message?.extendedTextMessage?.text ?? '').trim();
if (event !== 'messages.upsert' || key.fromMe === true || !jid.endsWith('@s.whatsapp.net') || !text) return [];
const lower = text.toLowerCase();
let reply;
if (/^(halo|hai|hi|hello|menu|p)$/i.test(lower)) {
  reply = 'Halo! 👋 Selamat datang di chatbot n8n.\n\nKetik:\n1 - Info layanan\n2 - Jam operasional\n3 - Bantuan';
} else if (lower === '1') {
  reply = 'Ini adalah demo chatbot n8n + Evolution API. Silakan sesuaikan info layanan.';
} else if (lower === '2') {
  reply = 'Jam operasional demo: Senin–Jumat, 09.00–17.00 WIB.';
} else if (lower === '3') {
  reply = 'Silakan tulis pertanyaan. Untuk kembali ke menu, ketik MENU.';
} else {
  reply = 'Pesan diterima ✅\nKetik MENU untuk melihat pilihan.';
}
return [{ json: { number: jid.split('@')[0], reply, instance: String(payload.instance ?? 'bot-local') } }];
